'use strict';
const palette = require('palette');

function paint(name, text) {
	const pair = palette[name];
	return pair === undefined ? text : pair.open + text + pair.close;
}

function names() {
	return Object.keys(palette);
}

function assembled() {
	return palette.assembled;
}

exports.paint = paint;
exports.names = names;
exports.assembled = assembled;
